// ---- src/run/RunMap.js (bundled, import/export stripped) ----
const NODE_TYPES = Object.freeze({
  FIGHT: 'fight',
  REST: 'rest',
  BOSS: 'boss',
});

// A branching, floor-by-floor node map. Every floor's nodes connect forward
// to at least one node in the next floor, so every node is reachable from
// somewhere in floor 0, and the single boss node in the final floor is
// reachable from every path through the map.
class RunMap {
  constructor(floors) {
    this.floors = floors;
  }

  get startingNodes() {
    return this.floors[0];
  }

  get bossNode() {
    return this.floors[this.floors.length - 1][0];
  }

  allNodes() {
    return this.floors.flat();
  }

  getNode(id) {
    return this.allNodes().find((n) => n.id === id);
  }
}

// Generates a RunMap. `rng` is injectable for deterministic tests.
// `enemyPool` (factory functions) is assigned randomly to fight nodes so
// each node knows which enemy it holds; `bossFactory` is assigned to the
// single boss node. Both are optional -- callers that don't pass them just
// get a map without pre-assigned encounters.
function generateRunMap({
  floorCount = 5,
  nodesPerFloor = 3,
  restChance = 0.25,
  rng = Math.random,
  enemyPool = [],
  bossFactory = null,
} = {}) {
  if (floorCount < 2) {
    throw new Error('A run map needs at least 2 floors (one fight floor and a boss floor)');
  }
  if (nodesPerFloor < 1) {
    throw new Error('Each non-boss floor needs at least one node');
  }

  const floors = [];
  for (let f = 0; f < floorCount - 1; f++) {
    const nodes = [];
    for (let i = 0; i < nodesPerFloor; i++) {
      const type = rng() < restChance ? NODE_TYPES.REST : NODE_TYPES.FIGHT;
      const node = { id: `f${f}n${i}`, floor: f, type, connections: [] };
      if (type === NODE_TYPES.FIGHT && enemyPool.length > 0) {
        node.enemyFactory = enemyPool[Math.floor(rng() * enemyPool.length)];
      }
      nodes.push(node);
    }
    floors.push(nodes);
  }
  const bossNode = { id: `f${floorCount - 1}n0`, floor: floorCount - 1, type: NODE_TYPES.BOSS, connections: [] };
  if (bossFactory) bossNode.enemyFactory = bossFactory;
  floors.push([bossNode]);

  for (let f = 0; f < floors.length - 1; f++) {
    const current = floors[f];
    const next = floors[f + 1];

    for (const node of current) {
      const linkCount = Math.min(next.length, rng() < 0.5 ? 1 : 2);
      node.connections = shuffle(next, rng)
        .slice(0, linkCount)
        .map((target) => target.id);
    }

    // Guarantee every node in the next floor is reachable from this one.
    for (const node of next) {
      const hasIncoming = current.some((c) => c.connections.includes(node.id));
      if (!hasIncoming) {
        const source = current[Math.floor(rng() * current.length)];
        source.connections.push(node.id);
      }
    }
  }

  return new RunMap(floors);
}


// ---- src/run/Run.js (bundled, import/export stripped) ----
// Drives sequential progression through a RunMap: pick a reachable node,
// resolve it (fight/rest), and move on -- ending in victory at the boss
// node or defeat if the player's Faith ever breaks. Console-output only;
// `log` is injectable for tests.
class Run {
  constructor({ map, player, log = () => {} }) {
    this.map = map;
    this.player = player;
    this.log = log;
    this.currentNode = null;
    this.visited = [];
    this.over = false;
    this.result = null; // 'victory' | 'defeat'
    this.log(`[Background: ${BACKGROUNDS.mapScreen}] The Shard Network unfolds.`);
  }

  // Nodes reachable right now: floor 0 if the run hasn't started, otherwise
  // whatever the current node connects to.
  availableNodes() {
    if (this.over) return [];
    if (!this.currentNode) return this.map.startingNodes;
    return this.currentNode.connections.map((id) => this.map.getNode(id));
  }

  enterNode(nodeId) {
    if (this.over) throw new Error('The run has already ended');
    const node = this.availableNodes().find((n) => n.id === nodeId);
    if (!node) throw new Error(`Node ${nodeId} is not reachable from here`);
    this.currentNode = node;
    this.visited.push(node.id);
    const background = node.type === NODE_TYPES.BOSS ? BACKGROUNDS.bossArena : BACKGROUNDS.nodeTransition;
    this.log(`[Background: ${background}]`);
    this.log(`-- Entering ${node.type} node ${node.id} (floor ${node.floor}) --`);
    return node;
  }

  // Marks the current node resolved. `victory: false` ends the run in
  // defeat (a lost fight); reaching the boss node in victory ends the run.
  completeCurrentNode({ victory = true } = {}) {
    if (!this.currentNode) throw new Error('No active node to complete');
    if (this.over) return;

    if (!victory) {
      this.over = true;
      this.result = 'defeat';
      this.log(`Run ends in defeat at ${this.currentNode.id}`);
      return;
    }

    if (this.currentNode.type === NODE_TYPES.BOSS) {
      this.over = true;
      this.result = 'victory';
      this.log('The final memory shard shatters. The run is complete.');
    }
  }

  // Convenience for resolving a rest node: heals the player and completes it.
  restAtCurrentNode(amount) {
    if (!this.currentNode || this.currentNode.type !== NODE_TYPES.REST) {
      throw new Error('Not currently at a rest node');
    }
    const healAmount = amount ?? Math.round(this.player.maxFaith * 0.3);
    this.player.heal(healAmount);
    this.log(
      `${this.player.name} rests, recovering ${healAmount} Faith ` +
        `(now ${this.player.faith}/${this.player.maxFaith})`
    );
    this.completeCurrentNode({ victory: true });
  }
}


// ---- src/run/backgrounds.js (bundled, import/export stripped) ----
// Background art wired to the three points in a run where the screen
// changes. Console-only for now -- Run logs these paths at the right
// moments so a future renderer has somewhere to read them from.
const BACKGROUNDS = Object.freeze({
  mapScreen: 'assets/backgrounds/bg_02_shard_network_nodemap.png',
  nodeTransition: 'assets/backgrounds/bg_01_the_fractured_descent_mapscreen.png',
  bossArena: 'assets/backgrounds/bg_03_the_bled_throne_bossfight.png',
});


// ---- src/narrative/NarrativeEngine.js (bundled, import/export stripped) ----
// Reveals a pool of story fragments ("memory shards") in randomized order as
// the player passes through nodes, tracks which have been seen via a flag
// set, and fires a one-time "recontextualization" event once enough shards
// have been collected. `rng` and `log` are injectable for deterministic
// tests.
class NarrativeEngine {
  constructor({ shards, threshold = 3, rng = Math.random, log = () => {} }) {
    if (threshold < 1) throw new Error('threshold must be at least 1');
    this.threshold = threshold;
    this.log = log;
    this.pool = shuffle(shards, rng);
    this.revealed = [];
    this.seen = new Set();
    this.recontextualized = false;
    this.twist = null;
  }

  get remaining() {
    return this.pool.length;
  }

  hasSeen(shardId) {
    return this.seen.has(shardId);
  }

  // Reveals the next shard from the randomized pool, or null once exhausted.
  revealNext() {
    if (this.pool.length === 0) return null;
    const shard = this.pool.shift();
    this.revealed.push(shard);
    this.seen.add(shard.id);
    this.log(`[Memory Shard] ${shard.text}`);
    this._maybeRecontextualize();
    return shard;
  }

  _maybeRecontextualize() {
    if (this.recontextualized || this.revealed.length < this.threshold) return null;
    this.recontextualized = true;
    const affected = [...new Set(this.revealed.map((s) => s.about).filter(Boolean))];
    this.twist = {
      type: 'recontextualization',
      affected,
      message: affected.length
        ? `Recontextualization: everything you thought you knew about ${affected.join(', ')} was a lie.`
        : 'Recontextualization: everything you thought you knew was a lie.',
    };
    this.log(`*** ${this.twist.message} ***`);
    return this.twist;
  }
}


